const rows = $input.all().map(i => i.json);
const ctx = $('Baue Query (Liste/Detail)').first().json;
let nav = {};
try { nav = $('Nav laden (GET)').first().json; } catch (e1) {
  try { nav = $('Nav laden (POST)').first().json; } catch (e2) { nav = {}; }
}

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function tickerListe(json) {
  try {
    const arr = Array.isArray(json) ? json : JSON.parse(json || '[]');
    return arr.length ? arr.map(t => esc(typeof t === 'string' ? t : (t.ticker || JSON.stringify(t)))).join(', ') : '-';
  } catch (e) { return '-'; }
}

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:1000px;margin:0 auto;}'
  + 'h1{font-size:22px;color:#fff;margin-bottom:4px;} h2{font-size:15px;color:#fff;margin-top:24px;margin-bottom:8px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:16px;} .hint{color:#9aa0a6;font-size:12px;}'
  + '.card{background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:14px 18px;margin-bottom:10px;}'
  + '.card h3{margin:0 0 4px 0;font-size:14px;color:#fff;font-weight:600;} .card a{color:#8ab4f8;text-decoration:none;}'
  + '.kpi-row{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0;}'
  + '.kpi{background:#1a1c20;padding:10px 16px;border-radius:6px;min-width:110px;}'
  + '.kpi .label{font-size:10px;color:#999;text-transform:uppercase;} .kpi .value{font-size:16px;color:#fff;margin-top:2px;}'
  + '.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;}'
  + '.badge.ok{background:#1c3a2a;color:#6bcf8e;} .badge.warn{background:#3a2c1c;color:#e0a854;}'
  + '.badge.danger{background:#3a1c1c;color:#e0665a;} .badge.muted{background:#22242a;color:#7a7d84;}'
  + 'button{background:#5b8def;border:none;color:#0f1115;font-weight:600;border-radius:6px;padding:8px 14px;font-size:12px;cursor:pointer;margin:4px 6px 4px 0;}'
  + 'button:hover{background:#7ba3f2;} button.danger{background:#e0665a;color:#fff;} button.danger:hover{background:#ef8177;}'
  + 'button.secondary{background:#2a2d34;color:#e6e6e6;} button.secondary:hover{background:#3a3d44;}'
  + 'textarea{background:#0f1115;border:1px solid #2a2d34;color:#e6e6e6;border-radius:6px;padding:6px 8px;font-size:13px;box-sizing:border-box;width:100%;min-height:60px;margin-top:6px;}'
  + '.section-empty{color:#7a7d84;font-size:12px;font-style:italic;margin-bottom:10px;}'
  + '.urteil-form{background:#1a1c20;border:1px solid #2a2d34;border-radius:6px;padding:14px;margin-top:10px;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

let html;

if (ctx.mode === 'liste') {
  const row = rows[0] || {};
  const zuBestaetigen = row.zu_bestaetigen || [];
  const unsicher = row.unsicher || [];
  const kiVerworfen = row.ki_verworfen || [];
  const vorfilterVerworfen = row.vorfilter_verworfen || [];
  const gemeldeteFalseNeg = row.gemeldete_false_negatives || [];
  const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

  function newsCard(n, extra) {
    return '<div class="card">'
      + '<h3><a href="/webhook/news-pruefen?id=' + esc(n.news_id) + '">' + esc(n.title) + '</a></h3>'
      + '<div class="hint">' + esc(n.source || '-') + ' &middot; ' + fmtDate(n.published_at) + '</div>'
      + (extra || '')
      + '</div>';
  }

  function section(titel, items, emptyText, renderer) {
    return '<h2>' + esc(titel) + ' (' + items.length + ')</h2>'
      + (items.length === 0
        ? '<div class="section-empty">' + esc(emptyText) + '</div>'
        : items.map(renderer).join(''));
  }

  const zuBestaetigenHtml = section('Zu bestätigen', zuBestaetigen, 'Nichts Offenes.', n =>
    newsCard(n, '<div class="hint">Ticker: ' + tickerListe(n.betroffene_ticker_json) + ' &middot; Wirkung: ' + esc(n.wirkungsrichtung || '-') + ' &middot; Konfidenz: ' + esc(n.relevance_confidence ?? n.konfidenz ?? '-') + '</div>')
  );
  const unsicherHtml = section('Unsicher / niedrige Konfidenz', unsicher, 'Nichts Offenes.', n =>
    newsCard(n, '<div class="hint">Ticker: ' + tickerListe(n.betroffene_ticker_json) + ' &middot; Konfidenz: ' + esc(n.relevance_confidence ?? '-') + '</div>')
  );
  const kiVerworfenHtml = section('KI hat verworfen (Kandidaten für False Negative)', kiVerworfen, 'Nichts Offenes.', n =>
    newsCard(n, n.wirkungs_begruendung ? '<div class="hint">' + esc(n.wirkungs_begruendung) + '</div>' : '')
  );
  const vw = row.vorfilter_wirksamkeit || {};
  const vwGeprueft = Number(vw.geprueft || 0);
  const vwDurchgelassen = Number(vw.durchgelassen || 0);
  const vwQuote = vwGeprueft > 0 ? ((vwDurchgelassen / vwGeprueft) * 100).toFixed(1) + '%' : '-';
  const vorfilterWirksamkeitHtml = '<h2>Vorfilter-Wirksamkeit (letzte 7 Tage)</h2>'
    + (Number(vw.anzahl_laeufe || 0) === 0
      ? '<div class="section-empty">Noch keine Daten - die Zaehlung wurde gerade erst eingebaut, sie fuellt sich mit dem naechsten stuendlichen Lauf.</div>'
      : '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Artikel geprüft</div><div class="value">' + vwGeprueft + '</div></div>'
        + '<div class="kpi"><div class="label">Durchgelassen</div><div class="value">' + vwDurchgelassen + '</div></div>'
        + '<div class="kpi"><div class="label">Durchlassquote</div><div class="value">' + vwQuote + '</div></div>'
        + '<div class="kpi"><div class="label">Hart ausgeschlossen</div><div class="value">' + esc(vw.hart_ausgeschlossen ?? 0) + '</div></div>'
        + '<div class="kpi"><div class="label">Soft-Noise ohne Marktbezug</div><div class="value">' + esc(vw.soft_noise_ausgeschlossen ?? 0) + '</div></div>'
        + '<div class="kpi"><div class="label">Kein Treffer</div><div class="value">' + esc(vw.kein_treffer ?? 0) + '</div></div>'
        + '</div>'
        + '<div class="hint">' + esc(vw.anzahl_laeufe) + ' Laeufe seit ' + fmtDate(vw.letzter_lauf) + '. Zaehlt nur Summen je Lauf, keine Einzelartikel.</div>');

  const hf = row.historischer_filter_wirksamkeit || {};
  const hfTrefferGesamt = Number(hf.treffer_gesamt || 0);
  const hfDurchgelassen = Number(hf.ticker_matched || 0) + Number(hf.ticker_ambiguous || 0);
  const hfGeprueft = hfDurchgelassen + Number(hf.ticker_ausgeschlossen || 0);
  const hfQuote = hfGeprueft > 0 ? ((hfDurchgelassen / hfGeprueft) * 100).toFixed(1) + '%' : '-';
  const historischerFilterHtml = '<h2>Historischer Filter-Wirksamkeit (Workflow 16, Ticker-Ausschlussregeln)</h2>'
    + (Number(hf.aktive_regeln || 0) === 0
      ? '<div class="section-empty">Noch keine aktiven Ausschlussregeln - erst ueber die Lernkandidaten-Seite Vorschlaege freigeben.</div>'
      : '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Aktive Regeln</div><div class="value">' + esc(hf.aktive_regeln ?? 0) + '</div></div>'
        + '<div class="kpi"><div class="label">Ticker-Matches geprüft</div><div class="value">' + hfGeprueft + '</div></div>'
        + '<div class="kpi"><div class="label">Durchgelassen</div><div class="value">' + hfDurchgelassen + '</div></div>'
        + '<div class="kpi"><div class="label">Durchlassquote</div><div class="value">' + hfQuote + '</div></div>'
        + '<div class="kpi"><div class="label">Vermiedene KI-Aufrufe (gesamt)</div><div class="value">' + hfTrefferGesamt + '</div></div>'
        + '<div class="kpi"><div class="label">Treffer (7 Tage)</div><div class="value">' + esc(hf.treffer_7_tage ?? 0) + '</div></div>'
        + '<div class="kpi"><div class="label">Validierungsstichprobe (7 Tage)</div><div class="value">' + esc(hf.stichprobe_7_tage ?? 0) + '</div></div>'
        + '<div class="kpi"><div class="label">Offene Lernkandidaten</div><div class="value">' + esc(hf.offene_lernkandidaten ?? 0) + '</div></div>'
        + '</div>'
        + '<div class="hint">Letzter Treffer: ' + fmtDate(hf.letzter_treffer) + '. Jede aktive Regel verhindert seither automatisch, dass ein bekannter Fehltreffer erneut zur teuren KI-Bewertung (Workflow 16b) geschickt wird. <a href="/webhook/historische-news-lernkandidaten">Lernkandidaten pruefen</a> &middot; <a href="/webhook/historische-news-ausschluesse">Aktive Regeln ansehen</a>.</div>');

  const vorfilterHtml = section('Vom Regex-Vorfilter verworfen (Einzelartikel)', vorfilterVerworfen, 'Keine (nur Summenzahlen werden gezaehlt, siehe oben - einzelne verworfene Artikel werden weiterhin nicht gespeichert).', n =>
    newsCard(n, n.discarded_reason ? '<div class="hint">Grund: ' + esc(n.discarded_reason) + '</div>' : '')
  );
  const gemeldeteHtml = section('Bereits gemeldete mögliche False Negatives', gemeldeteFalseNeg, 'Keine offenen Meldungen.', f =>
    '<div class="card"><h3><a href="/webhook/news-pruefen?id=' + esc(f.news_id) + '">' + esc(f.title) + '</a></h3>'
    + '<div class="hint">Status: <span class="badge warn">' + esc(f.status) + '</span> &middot; gemeldet: ' + fmtDate(f.created_at) + '</div>'
    + (f.grund ? '<div class="hint">"' + esc(f.grund) + '"</div>' : '')
    + '</div>'
  );

  html = pageWrap('News Prüfen', ''
    + '<h1>News Prüfen</h1>'
    + '<div class="meta">Stand: ' + now + '</div>'
    + zuBestaetigenHtml + unsicherHtml + kiVerworfenHtml + vorfilterWirksamkeitHtml + historischerFilterHtml + vorfilterHtml + gemeldeteHtml);
} else {
  const n = rows[0];
  if (!n || !n.id) {
    html = pageWrap('News Prüfen', '<h1>News Prüfen</h1><div class="card">News nicht gefunden. <a href="/webhook/news-pruefen">Zurück zur Liste</a></div>');
  } else {
    const relevantBadge = n.relevant === true ? '<span class="badge ok">relevant</span>'
      : n.relevant === false ? '<span class="badge danger">irrelevant</span>'
      : '<span class="badge muted">nicht bewertet</span>';

    const bisherigeNotiz = n.bisheriges_urteil
      ? '<div class="card" style="border-color:#5b8def;"><strong>Bisherige Notiz:</strong> ' + esc(n.bisheriges_urteil)
        + (n.notiz_reviewed_at ? ' am ' + fmtDate(n.notiz_reviewed_at) : '')
        + (n.bisheriger_kommentar ? '<div class="hint">"' + esc(n.bisheriger_kommentar) + '"</div>' : '')
        + '</div>'
      : '';

    const bisherigeMeldung = n.false_negative_flag_id
      ? '<div class="card" style="border-color:#e0a854;"><strong>Bereits als möglicher False Negative gemeldet</strong> &middot; Status: <span class="badge warn">' + esc(n.false_negative_status) + '</span>'
        + (n.false_negative_grund ? '<div class="hint">"' + esc(n.false_negative_grund) + '"</div>' : '')
        + '</div>'
      : '';

    const assessmentHtml = n.assessment_id
      ? '<div class="kpi-row">'
        + '<div class="kpi"><div class="label">Relevanz</div><div class="value">' + relevantBadge + '</div></div>'
        + '<div class="kpi"><div class="label">Wirkungsrichtung</div><div class="value">' + esc(n.wirkungsrichtung || '-') + '</div></div>'
        + '<div class="kpi"><div class="label">Wirkung Stärke</div><div class="value">' + esc(n.wirkung_staerke || '-') + '</div></div>'
        + '<div class="kpi"><div class="label">Konfidenz</div><div class="value">' + esc(n.relevance_confidence ?? n.konfidenz ?? '-') + '</div></div>'
        + '</div>'
        + '<div class="hint">Ticker: ' + tickerListe(n.betroffene_ticker_json) + '</div>'
        + (n.ticker_begruendung ? '<div class="hint">Ticker-Begründung: ' + esc(n.ticker_begruendung) + '</div>' : '')
        + (n.wirkungs_begruendung ? '<div class="hint">Wirkungs-Begründung: ' + esc(n.wirkungs_begruendung) + '</div>' : '')
        + '<div class="hint">Bisheriger Bestätigungsstatus: ' + esc(n.confirmation_status || 'unconfirmed') + '</div>'
      : '<div class="hint">Noch keine KI-Bewertung vorhanden' + (n.status === 'filtered' ? ' - vom Regex-Vorfilter verworfen, bevor eine Bewertung stattfand.' : '.') + '</div>';

    html = pageWrap('News prüfen', ''
      + '<a href="/webhook/news-pruefen" class="hint">&larr; Zurück zur Liste</a>'
      + '<h1>' + esc(n.title) + '</h1>'
      + '<div class="meta">' + esc(n.source || '-') + ' &middot; ' + fmtDate(n.published_at) + ' &middot; Status: ' + esc(n.status) + (n.url ? ' &middot; <a href="' + esc(n.url) + '" target="_blank">Original</a>' : '') + '</div>'
      + bisherigeNotiz + bisherigeMeldung

      + '<h2>Bewertung</h2>' + assessmentHtml

      + (n.article_text ? '<h2>Artikeltext</h2><div class="hint" style="white-space:pre-wrap;">' + esc(n.article_text.slice(0, 2000)) + (n.article_text.length > 2000 ? ' [...]' : '') + '</div>' : '')

      + '<h2>Urteil</h2>'
      + '<div class="urteil-form">'
      + '<form id="form-urteil" method="POST" action="/webhook/news-review-abgeben">'
      + '<input type="hidden" name="news_id" value="' + esc(n.id) + '">'
      + '<textarea name="kommentar" placeholder="Kommentar / Begründung (optional)"></textarea>'
      + '<div style="margin-top:8px;">'
      + '<button type="submit" name="action" value="relevant">RELEVANT</button>'
      + '<button type="submit" name="action" value="irrelevant" class="secondary">IRRELEVANT</button>'
      + '<button type="submit" name="action" value="unsicher" class="secondary">UNSICHER</button>'
      + '<button type="submit" name="action" value="falsch_bewertet" class="secondary">FALSCH BEWERTET</button>'
      + '<button type="submit" name="action" value="filter_falsch" class="danger">FILTER HAT FALSCH ENTSCHIEDEN</button>'
      + '</div>'
      + '</form>'
      + '<div class="hint">RELEVANT/IRRELEVANT bestätigen die KI-Einschätzung. UNSICHER/FALSCH BEWERTET halten eine abweichende Einschätzung fest, ändern aber nichts automatisch. FILTER HAT FALSCH ENTSCHIEDEN meldet einen möglichen False Negative zur späteren Regelprüfung - keine Aktion ändert sofort eine Regel.</div>'
      + '</div>'
    );
  }
}

return [{ json: { html } }];

// $json ist hier "Nav laden (POST)" (Nav-Call INLINE vor diesem Node) - Trigger-Daten deshalb
// per Namens-Lookup statt aus $json, gleiches Muster wie die anderen Human-in-the-Loop-Seiten.
const trigger = $('Webhook POST (Review)').first().json;
const j = trigger.body || trigger;

function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

const newsId = pgNum(j.news_id);
const VALID_ACTIONS = new Set(['relevant', 'irrelevant', 'unsicher', 'falsch_bewertet', 'filter_falsch']);
const action = VALID_ACTIONS.has(String(j.action || '').trim()) ? String(j.action).trim() : null;
const kommentar = String(j.kommentar || '').trim();

return {
  json: {
    news_id: newsId,
    action,
    kommentar,
    // Nur assessment_id/status frisch laden - inhaltliche Werte kommen nie aus dem Body.
    load_sql: newsId
      ? `SELECT ni.id, ni.status, vla.assessment_id
           FROM trading.news_items ni
           LEFT JOIN trading.v_news_latest_assessment vla ON vla.news_id = ni.id
           WHERE ni.id = ${newsId};`
      : `SELECT NULL::bigint AS id WHERE FALSE;`
  }
};

// $json ist hier das Ergebnis von "DB: News laden (fuer Review)" (frisch geladen: id/status/
// assessment_id). ctx = die aus dem Body vertrauten Steuerfelder (news_id/action/kommentar).
function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

const loaded = $json;
const ctx = $('POST: Baue Load-Query').first().json;
const { news_id, action, kommentar } = ctx;

let sql;

if (!news_id || !action || !loaded || !loaded.id) {
  sql = 'SELECT 1;';
} else if (action === 'filter_falsch') {
  // Eigene Tabelle, kein UPSERT: jede Meldung ist ein eigenes Ereignis (sql/071, Modul 4).
  sql = `INSERT INTO trading.news_false_negative_flags (news_id, grund)
    VALUES (${news_id}, ${pgStr(kommentar || null)});`;
} else if (action === 'relevant' || action === 'irrelevant') {
  const confirmationStatus = action === 'relevant' ? 'manually_confirmed' : 'manually_rejected';
  // Bestehenden Hook (sql/012) nur setzen, wenn es ueberhaupt eine Bewertung gibt - bei
  // status='filtered' (Vorfilter-Fund, nie von der KI bewertet) existiert keine.
  const confirmationUpdate = loaded.assessment_id
    ? `UPDATE trading.news_assessments SET confirmation_status = ${pgStr(confirmationStatus)} WHERE id = ${loaded.assessment_id};`
    : '';
  sql = `BEGIN;
    ${confirmationUpdate}
    INSERT INTO trading.news_review_notes (news_id, urteil, kommentar, reviewed_von)
      VALUES (${news_id}, ${pgStr(action)}, ${pgStr(kommentar || null)}, 'nutzer')
      ON CONFLICT (news_id) DO UPDATE SET
        urteil = EXCLUDED.urteil, kommentar = EXCLUDED.kommentar,
        reviewed_von = EXCLUDED.reviewed_von, reviewed_at = now();
    COMMIT;`;
} else {
  // unsicher / falsch_bewertet: nur Notiz, kein confirmation_status-Wechsel (siehe sql/072-Kommentar).
  sql = `INSERT INTO trading.news_review_notes (news_id, urteil, kommentar, reviewed_von)
    VALUES (${news_id}, ${pgStr(action)}, ${pgStr(kommentar || null)}, 'nutzer')
    ON CONFLICT (news_id) DO UPDATE SET
      urteil = EXCLUDED.urteil, kommentar = EXCLUDED.kommentar,
      reviewed_von = EXCLUDED.reviewed_von, reviewed_at = now();`;
}

return [{ json: { sql, mode: 'detail_nach_post', news_id } }];
